const KEY = 'artbench.lang';
let current = 'en';
try { current = DICTS[localStorage.getItem(KEY)] ? localStorage.getItem(KEY) : 'en'; } catch { current = 'en'; }

export const lang = () => current;
export const locale = () => (current === 'tr' ? 'tr-TR' : 'en-US');
export function setLang(code) {
  if (!DICTS[code]) return;
  current = code;
  try { localStorage.setItem(KEY, code); } catch { /* private window or blocked storage: the choice just does not persist */ }
  document.documentElement.lang = code;
}
document.documentElement.lang = current;

/** The string for `key` in the current language (English when a translation is missing), with {vars} filled in. */
export function t(key, vars) {
  let s = DICTS[current][key] ?? EN[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}
